import React from 'react';

import type { DataTestId } from '../../core/types/data-props.js';
import type { DOMProps } from '../../core/types/dom.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Paragraph } from '../../typography/Paragraph.js';
import { Text } from '../../typography/Text.js';
//#region Typings
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface TerminologyDescriptionProps
  extends DOMProps,
    WithChildren,
    StylingProps,
    DataTestId {}
//#endregion Typings

/** Adds the description for the terminology to help the user. */
export const Description = (props: TerminologyDescriptionProps) => {
  const {
    children,
    id,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;
  if (typeof children === 'string') {
    return (
      <Paragraph
        id={id}
        data-testid={dataTestId}
        className={consumerClassName}
        style={consumerStyle}
      >
        {children}
      </Paragraph>
    );
  }
  return (
    <Text as="div" textStyle="base" id={id}>
      {children}
    </Text>
  );
};

Description.displayName = 'TerminologyOverlay.Description';
